#!/usr/bin/env python3
"""Generate atari800_roms.h from the Atari ROM images in Distribution/Rom.

emcc's -sSTANDALONE_WASM build does not support opening files (fopen is not
wired to WASI path_open in this Emscripten version), so the WASI module
embeds the ROMs as C arrays.  This script converts the binary ROM files
into a C header that the (guarded) Atari800 core reads via a fallback in
Atari800_LoadImage().

Usage:
    python3 gen_roms.py
"""

from pathlib import Path

HERE = Path(__file__).resolve().parent
ROM_DIR = HERE.parent / "Atari800Win-PLus" / "Distribution" / "Rom"

# (filename, C array name)
ROMS = [
    ("ATARIXL.ROM", "g_rom_atarixl"),
    ("ATARIBAS.ROM", "g_rom_ataribas"),
    ("ATARIOSB.ROM", "g_rom_atariosb"),
]


def emit_array(fh, name: str, data: bytes) -> None:
    fh.write(f"static const uint8_t {name}[{len(data)}] = {{\n")
    for i in range(0, len(data), 16):
        fh.write("    " + ",".join(f"0x{b:02X}" for b in data[i:i + 16]) + ",\n")
    fh.write("};\n")


def main() -> None:
    out = HERE / "atari800_roms.h"
    with open(out, "w") as fh:
        fh.write("/* Generated by gen_roms.py - do not edit. */\n")
        fh.write("#ifndef ATARI800_ROMS_H_\n")
        fh.write("#define ATARI800_ROMS_H_\n\n")
        fh.write("#include <stdint.h>\n\n")
        for filename, cname in ROMS:
            src = ROM_DIR / filename
            if not src.is_file():
                raise SystemExit(f"missing ROM: {src}")
            data = src.read_bytes()
            print(f"{filename}: {len(data)} bytes")
            emit_array(fh, cname, data)
            fh.write("\n")
        fh.write("#endif /* ATARI800_ROMS_H_ */\n")
    print(f"wrote {out}")


if __name__ == "__main__":
    main()
